// IANA tzdata 2026d, generated by scripts/generate_intl_tzdata.py.
// Source SHA-256: 0cb2aa8e333c3dc049badc42a0c61f21987b8cd44e107fa900bad764aacc7767
// Table SHA-256: 0bd177c49e4a83cf96d3c85be7c159fc12e50f479642782df18cfe17ade66744

#[derive(Debug)]
struct TzZone {
    name: String,
    canonical: String,
    initial_offset_seconds: i32,
    transitions: Vec<(i64, i32)>,
}

fn tz_zones() -> &'static [TzZone] {
    static ZONES: std::sync::OnceLock<Vec<TzZone>> = std::sync::OnceLock::new();
    ZONES.get_or_init(|| {
        let data = include_bytes!("builtins_intl_tzdata.bin");
        assert_eq!(&data[..4], b"ATZ1");
        let mut position = 4;
        let mut read = |bytes: usize| {
            let next = position + bytes;
            let result = &data[position..next];
            position = next;
            result
        };
        let count = u16::from_be_bytes(read(2).try_into().unwrap());
        let mut zones = Vec::with_capacity(count as usize);
        for _ in 0..count {
            let name_len = read(1)[0] as usize;
            let name = std::str::from_utf8(read(name_len)).unwrap().to_owned();
            let canonical_len = read(1)[0] as usize;
            let canonical = std::str::from_utf8(read(canonical_len)).unwrap().to_owned();
            let initial_offset_seconds = i32::from_be_bytes(read(4).try_into().unwrap());
            let transition_count = u32::from_be_bytes(read(4).try_into().unwrap());
            let mut transitions = Vec::with_capacity(transition_count as usize);
            for _ in 0..transition_count {
                let epoch = i64::from_be_bytes(read(8).try_into().unwrap());
                let offset = i32::from_be_bytes(read(4).try_into().unwrap());
                transitions.push((epoch, offset));
            }
            zones.push(TzZone { name, canonical, initial_offset_seconds, transitions });
        }
        zones
    })
}

fn tz_zone(id: &str) -> Option<&'static TzZone> {
    let zones = tz_zones();
    let entry = zones.iter().find(|zone| zone.name.eq_ignore_ascii_case(id))?;
    if entry.name == entry.canonical { Some(entry) }
    else { zones.iter().find(|zone| zone.name == entry.canonical) }
}

fn tz_fixed_offset_seconds(id: &str) -> Option<i32> {
    let bytes = id.as_bytes();
    let sign = match bytes.first()? { b'+' => 1, b'-' => -1, _ => return None };
    let digits = match bytes {
        [_, a, b] if a.is_ascii_digit() && b.is_ascii_digit() => {
            String::from_utf8(vec![*a, *b]).ok()?
        }
        [_, a, b, c, d] if [a, b, c, d].iter().all(|b| b.is_ascii_digit()) => {
            String::from_utf8(vec![*a, *b, *c, *d]).ok()?
        }
        [_, a, b, b':', c, d] if [a, b, c, d].iter().all(|b| b.is_ascii_digit()) => {
            String::from_utf8(vec![*a, *b, *c, *d]).ok()?
        }
        _ => return None,
    };
    let hours = digits[..2].parse::<i32>().ok()?;
    let minutes = if digits.len() == 4 { digits[2..].parse::<i32>().ok()? } else { 0 };
    if hours > 23 || minutes > 59 { return None; }
    Some(sign * (hours * 3600 + minutes * 60))
}

/// Canonical IANA identifier, or normalized fixed-offset identifier.
/// Preserves the Etc/UTC and Etc/GMT spellings required by ECMA-402.
pub(crate) fn tz_canonicalize(id: &str) -> Option<String> {
    if ["UTC", "Etc/UTC", "Etc/GMT"].iter().any(|name| name.eq_ignore_ascii_case(id)) {
        return Some(["UTC", "Etc/UTC", "Etc/GMT"].into_iter()
            .find(|name| name.eq_ignore_ascii_case(id)).unwrap().into());
    }
    if id.eq_ignore_ascii_case("GMT") { return Some("UTC".into()); }
    if let Some(seconds) = tz_fixed_offset_seconds(id) {
        let minutes = seconds.unsigned_abs() / 60;
        return Some(format!("{}{:02}:{:02}", if seconds < 0 { '-' } else { '+' },
            minutes / 60, minutes % 60));
    }
    let zones = tz_zones();
    let zone = zones.iter().find(|zone| zone.name.eq_ignore_ascii_case(id))?;
    Some(zone.canonical.clone())
}

/// Offset from UTC in nanoseconds at an exact epoch nanosecond.
pub(crate) fn tz_offset_ns(id: &str, epoch_ns: i128) -> i128 {
    if let Some(offset) = tz_fixed_offset_seconds(id) { return offset as i128 * 1_000_000_000; }
    if ["UTC", "Etc/UTC", "Etc/GMT", "GMT"].iter().any(|name| name.eq_ignore_ascii_case(id)) {
        return 0;
    }
    let zone = tz_zone(id).expect("tz_offset_ns requires a canonical time zone");
    let second = epoch_ns.div_euclid(1_000_000_000);
    let index = zone.transitions.partition_point(|(at, _)| (*at as i128) <= second);
    let offset = if index == 0 { zone.initial_offset_seconds } else { zone.transitions[index - 1].1 };
    offset as i128 * 1_000_000_000
}

/// Exact instants whose wall-clock nanosecond equals `local_ns` in this zone.
/// A gap returns zero, an ordinary time one, and a fold two instants.
pub(crate) fn tz_possible_epoch_ns(id: &str, local_ns: i128) -> Vec<i128> {
    if let Some(offset) = tz_fixed_offset_seconds(id) {
        return vec![local_ns - offset as i128 * 1_000_000_000];
    }
    if ["UTC", "Etc/UTC", "Etc/GMT", "GMT"].iter().any(|name| name.eq_ignore_ascii_case(id)) {
        return vec![local_ns];
    }
    let zone = tz_zone(id).expect("tz_possible_epoch_ns requires a canonical time zone");
    let mut offsets = vec![zone.initial_offset_seconds];
    for (_, offset) in &zone.transitions {
        if !offsets.contains(offset) { offsets.push(*offset); }
    }
    let mut possible = Vec::new();
    for offset in offsets {
        let instant = local_ns - offset as i128 * 1_000_000_000;
        if tz_offset_ns(id, instant) == offset as i128 * 1_000_000_000 {
            possible.push(instant);
        }
    }
    possible.sort_unstable();
    possible
}

pub(crate) fn tz_next_transition(id: &str, epoch_ns: i128) -> Option<i128> {
    let zone = tz_zone(id)?;
    zone.transitions.iter().find(|(at, _)| *at as i128 * 1_000_000_000 > epoch_ns)
        .map(|(at, _)| *at as i128 * 1_000_000_000)
}

pub(crate) fn tz_previous_transition(id: &str, epoch_ns: i128) -> Option<i128> {
    let zone = tz_zone(id)?;
    zone.transitions.iter().rev().find(|(at, _)| *at as i128 * 1_000_000_000 < epoch_ns)
        .map(|(at, _)| *at as i128 * 1_000_000_000)
}

#[cfg(test)]
mod intl_timezone_tests {
    use super::*;

    #[test]
    fn new_york_gap_fold_and_offsets() {
        let seconds = 1_710_054_000i128; // 2024-03-10 07:00 UTC
        assert_eq!(tz_offset_ns("America/New_York", (seconds - 1) * 1_000_000_000), -18_000_000_000_000);
        assert_eq!(tz_offset_ns("America/New_York", seconds * 1_000_000_000), -14_400_000_000_000);
        let wall_gap = (seconds - 5 * 3600 + 30 * 60) * 1_000_000_000;
        assert!(tz_possible_epoch_ns("America/New_York", wall_gap).is_empty());
        let wall_fold = 1_730_597_400i128 * 1_000_000_000; // 2024-11-03 01:30 wall time
        assert_eq!(tz_possible_epoch_ns("America/New_York", wall_fold).len(), 2);
    }
}
